(function () {
  const LX = globalThis.LX;
  const { T, H, P, STORY, TIP, WARN, FUN, BIG, JOB, CMD, TABLE, ANAT, PRE, THINK, STEPS, TRY } = LX.b;
  const { mcq, cmd } = LX.Q;
  const M = LX.M;
  const here = (name, lines) => `cat > ${name} <<'XEOF'\n${lines.join('\n')}\nXEOF`;
  const host = (sh, h) => LX.hostShell(sh, h);
  const tfState = (sh, dir) => { const n = sh.fs.lookup(dir + '/terraform.tfstate'); if (!n) return null; try { return JSON.parse(n.content); } catch (e) { return null; } };
  const tfRes = (st, type) => (st ? st.resources.filter((r) => r.type === type).reduce((n, r) => n + r.instances.length, 0) : 0);

  const TF0 = ['sudo apt install -y terraform'];

  const UD_GOOD = ['#cloud-config', 'hostname: web-02', 'packages:', '  - nginx', '  - htop', 'users:', '  - name: deploy', '    groups: [sudo]', '    shell: /bin/bash', '    sudo: "ALL=(ALL) NOPASSWD:ALL"', '    ssh_authorized_keys:', '      - ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAIExampleKeyForTheLab deploy@laptop', 'write_files:', '  - path: /etc/motd', '    content: |', '      Managed by cloud-init', '    permissions: "0644"', 'runcmd:', '  - systemctl enable --now nginx'];
  const UD_FIX = [here('user-data.yml', UD_GOOD), 'cloud-init schema --config-file user-data.yml', 'cloudlab boot user-data.yml'];
  const UD_BAD = ['hostname: web-03', 'packges:', '  - nginx', 'runcmd:', '  - echo hello > /tmp/hello'];
  const UD_BAD_LAB = [here('bad.yml', UD_BAD)];
  const UD_BAD_FIX = ['cloud-init schema --config-file bad.yml', 'sed -i "1i #cloud-config" bad.yml', 'sed -i "s/packges:/packages:/" bad.yml', 'cloud-init schema --config-file bad.yml'];

  const META_FIX = ['IID=$(curl -s http://169.254.169.254/latest/meta-data/instance-id)', 'AZ=$(curl -s http://169.254.169.254/latest/meta-data/placement/availability-zone)', 'IP=$(curl -s http://169.254.169.254/latest/meta-data/local-ipv4)', 'echo "id=$IID az=$AZ ip=$IP" > ~/instance.txt', 'cat ~/instance.txt'];
  const V2_LAB = ['sudo cloudlab imds v2-required'];
  const V2_FIX = ['curl -s -o /dev/null -w "%{http_code}\\n" http://169.254.169.254/latest/meta-data/instance-id', 'TOKEN=$(curl -s -X PUT http://169.254.169.254/latest/api/token -H "X-aws-ec2-metadata-token-ttl-seconds: 300")', 'curl -s -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/instance-id > ~/id.txt', 'cat ~/id.txt'];
  const VM_FIX = ['sudo apt install -y qemu-utils libvirt-clients', 'qemu-img create -f qcow2 ~/vm1.qcow2 20G', 'qemu-img resize ~/vm1.qcow2 +5G', 'qemu-img info ~/vm1.qcow2', 'sudo virsh list --all', 'sudo virsh start test-vm', 'sudo virsh list'];

  const TF_FILE = ['variable "owner" {', '  type    = string', '  default = "asha"', '}', '', 'resource "local_file" "motd" {', '  filename = "${path.module}/motd.txt"', '  content  = "Server managed by Terraform, owner: ${var.owner}\\n"', '}', '', 'output "motd_path" {', '  value = local_file.motd.filename', '}'];
  const TF1_FIX = TF0.concat(['mkdir ~/infra', 'cd ~/infra', here('main.tf', TF_FILE), 'terraform init', 'terraform plan', 'terraform apply -auto-approve', 'cat motd.txt']);
  const TF_CLOUD = ['variable "env" {', '  type    = string', '  default = "dev"', '}', '', 'resource "sandbox_bucket" "assets" {', '  name       = "acme-${var.env}-assets"', '  versioning = true', '}', '', 'resource "sandbox_server" "web" {', '  count = 2', '  name  = "web-${count.index}"', '  image = "ubuntu-24.04"', '  size  = "small"', '  tags  = { env = var.env }', '}', '', 'output "server_ips" {', '  value = sandbox_server.web[*].public_ip', '}'];
  const TF2_FIX = TF0.concat(['mkdir ~/cloud', 'cd ~/cloud', here('main.tf', TF_CLOUD), 'terraform init', 'terraform apply -auto-approve', 'terraform output server_ips', 'terraform state list']);
  const DRIFT_LAB = TF0.concat(['mkdir ~/drift', 'cd ~/drift', here('main.tf', ['resource "local_file" "conf" {', '  filename = "${path.module}/app.conf"', '  content  = "max_clients = 100\\n"', '}']), 'terraform init', 'terraform apply -auto-approve', 'echo "max_clients = 9999" > app.conf', 'cd ~']);
  const DRIFT_FIX = ['cd ~/drift', 'cat app.conf', 'terraform plan', 'terraform apply -auto-approve', 'cat app.conf', 'terraform plan'];

  const Q_TF = TF0.concat(['mkdir ~/q', 'cd ~/q', here('main.tf', ['resource "sandbox_bucket" "b" {', '  name = "acme-quiz"', '}', '', 'output "bucket" {', '  value = sandbox_bucket.b.arn', '}'])]);

  LX.topics.push({
    id: 'cloud',
    part: 5,
    no: 39,
    key: '☁',
    mins: 90,
    title: T('Virtualization, Cloud and Infrastructure as Code', 'Virtualization, Cloud aur Infrastructure as Code'),
    blurb: T('Where your Linux servers actually run today. Hypervisors and VMs, cloud models and the services every provider has, the instance metadata service, cloud-init for first-boot setup, and Terraform to create infrastructure from code.', 'Aaj tumhare Linux servers asal mein kahan chalte hain. Hypervisors aur VMs, cloud models aur har provider ke services, instance metadata service, pehli boot ke setup ke liye cloud-init, aur code se infrastructure banane ke liye Terraform.'),
    blocks: [
      BIG(
        'Almost no company racks its own servers any more: a Linux admin today works on **virtual machines** that run in a **cloud** (AWS, Azure, Google Cloud, or a private cloud like OpenStack/VMware). You still do everything from the earlier lessons (users, services, firewall, logs, backups), but the machine is created with an API call, billed by the hour, configured at first boot by **cloud-init**, and its surroundings (network, disks, load balancers) are defined as **code** with tools like **Terraform**. This lesson is the map and the first hands-on steps; each cloud provider then needs its own deeper course.',
        'Ab lagbhag koi company apne servers rack mein nahi lagati: aaj ka Linux admin **virtual machines** par kaam karta hai jo **cloud** mein chalti hain (AWS, Azure, Google Cloud, ya OpenStack/VMware jaisa private cloud). Pichhle lessons ka sab kuch (users, services, firewall, logs, backups) abhi bhi karte ho, par machine API call se banti hai, ghante ke hisaab se bill hoti hai, pehli boot par **cloud-init** se configure hoti hai, aur uske aas-paas (network, disks, load balancers) **code** mein likhe jate hain jaise **Terraform** se. Ye lesson naqsha aur pehle hands-on kadam hai; har cloud provider ke liye alag gehra course chahiye.'
      ),
      STORY(
        'Buying a server is like buying a house: big upfront cost, long wait, and you are stuck with it. The cloud is like hotels and serviced apartments: book a room by the night in any city in minutes, hand it back when done, pay only for the nights. **Infrastructure as Code** is the booking form that says exactly which room, which floor and which furniture you want: hand it to the hotel again and you get the identical room.',
        'Server kharidna ghar kharidne jaisa hai: shuru mein bada kharch, lamba intezar aur phans jana. Cloud hotels aur serviced apartments jaisa hai: kisi bhi shehar mein minuton mein raat ke hisaab se kamra book karo, kaam hone par wapas karo, sirf raaton ka paisa do. **Infrastructure as Code** wo booking form hai jisme likha hai kaun sa kamra, kaun si manzil aur kaun sa furniture chahiye: hotel ko dobara do to bilkul wahi kamra milta hai.'
      ),
      H('Virtualization: the technology underneath', 'Virtualization: neeche ki technology'),
      P('A **hypervisor** lets one physical machine run many isolated **virtual machines** (VMs), each with its own virtual CPU, RAM, disk, network card and its own kernel. **Type 1** hypervisors run directly on the hardware (KVM in Linux, VMware ESXi, Microsoft Hyper-V, Xen): this is what clouds use. **Type 2** run as an application on a normal OS (VirtualBox, VMware Workstation): what you use on a laptop. Modern CPUs help with hardware support (Intel **VT-x** = `vmx`, AMD **AMD-V** = `svm`). **KVM** turns the Linux kernel itself into a hypervisor and **QEMU** provides the virtual hardware; **libvirt** (`virsh`) manages them.', '**Hypervisor** ek physical machine par kai alag-alag **virtual machines** (VMs) chalane deta hai, har ek ka apna virtual CPU, RAM, disk, network card aur apna kernel. **Type 1** hypervisors seedha hardware par chalte hain (Linux ka KVM, VMware ESXi, Microsoft Hyper-V, Xen): clouds yahi use karte hain. **Type 2** normal OS par application ki tarah chalte hain (VirtualBox, VMware Workstation): laptop par tum yahi use karte ho. Modern CPUs hardware madad dete hain (Intel **VT-x** = `vmx`, AMD **AMD-V** = `svm`). **KVM** Linux kernel ko hi hypervisor bana deta hai, **QEMU** virtual hardware deta hai, aur **libvirt** (`virsh`) unhe manage karta hai.'),
      TABLE(
        [
          ['virtual machine', 'a full computer in software: own kernel, any OS, strong isolation, boots in tens of seconds, GBs of RAM/disk', 'software mein poora computer: apna kernel, koi bhi OS, majboot isolation, kuch sau second mein boot, GBs RAM/disk'],
          ['container', 'a process group sharing the HOST kernel (Docker lesson): starts in a second, MBs, weaker isolation. Containers usually run INSIDE VMs', 'HOST kernel share karne wale processes ka group (Docker lesson): ek second mein shuru, MBs, kamzor isolation. Containers aam taur par VMs ke ANDAR chalte hain'],
          ['bare metal', 'a physical server with no hypervisor: databases and special hardware (GPUs) sometimes need it', 'bina hypervisor ka physical server: databases aur khaas hardware (GPUs) ko kabhi-kabhi chahiye'],
          ['image / template', 'a disk file that a VM starts from (qcow2, raw, VMDK, AMI): a golden copy with the OS installed', 'disk file jisse VM shuru hoti hai (qcow2, raw, VMDK, AMI): OS install wali golden copy'],
          ['snapshot', 'the state of a VM disk at one moment: handy before an upgrade, but not a backup', 'ek pal par VM disk ki halat: upgrade se pehle kaam ka, par backup nahi'],
        ],
        'Word',
        'Shabd'
      ),
      CMD(['systemd-detect-virt', 'lscpu | grep -i -E "hypervisor|virtualization"', 'cat /sys/class/dmi/id/sys_vendor /sys/class/dmi/id/product_name', 'sudo dmidecode -s system-manufacturer', 'hostnamectl | grep -i virt', 'nproc', 'free -m | head -n 2', 'lsblk'], 'How do you know you are inside a VM, and on which platform? systemd-detect-virt says kvm; lscpu names the hypervisor; the DMI files show the platform (the sandbox pretends to be an Amazon EC2 t3.micro). On a physical host systemd-detect-virt prints none, and on a container it says docker or lxc with --container.', 'Kaise pata chale ki tum VM ke andar ho aur kis platform par? systemd-detect-virt kvm kehta hai; lscpu hypervisor ka naam batata hai; DMI files platform dikhati hain (sandbox Amazon EC2 t3.micro hone ka natak karta hai). Physical host par systemd-detect-virt none chhapta hai, aur container mein --container ke saath docker ya lxc.'),
      CMD(['sudo apt install -y qemu-utils libvirt-clients', 'qemu-img create -f qcow2 ~/web-vm.qcow2 20G', 'qemu-img info ~/web-vm.qcow2', 'qemu-img resize ~/web-vm.qcow2 +10G', 'qemu-img info ~/web-vm.qcow2 | head -n 3', 'sudo virsh list --all', 'sudo virsh dominfo test-vm', 'sudo virsh start test-vm', 'sudo virsh list', 'sudo virsh shutdown test-vm'], 'qcow2 is a copy-on-write disk format: a 20 GiB virtual disk takes only a few KiB until the guest writes data (thin provisioning), and it supports snapshots. virsh is the libvirt tool: list --all shows defined VMs, start/shutdown/destroy (destroy = pull the power) control them, dominfo shows the details. This is the layer that cloud platforms automate for you.', 'qcow2 copy-on-write disk format hai: 20 GiB ka virtual disk guest ke data likhne tak sirf kuch KiB leta hai (thin provisioning), aur snapshots support karta hai. virsh libvirt ka tool hai: list --all defined VMs dikhata hai, start/shutdown/destroy (destroy = bijli kheench lena) unhe control karte hain, dominfo vivaran dikhata hai. Cloud platforms isi layer ko tumhare liye automate karte hain.'),
      TIP('Virtualization has a cost you can see: in `top`, the **%st** (steal) value is CPU time the hypervisor gave to other VMs while yours wanted to run. A permanently high steal means a noisy neighbour or an undersized instance: ask for another instance type or host.', 'Virtualization ki ek keemat dikhti hai: `top` mein **%st** (steal) wo CPU samay hai jo hypervisor ne doosri VMs ko diya jab tumhari VM chalna chahti thi. Hamesha zyada steal matlab shor machane wala padosi ya chhota instance: doosra instance type ya host maango.'),
      H('The cloud in one table', 'Cloud ek table mein'),
      TABLE(
        [
          ['IaaS', 'Infrastructure as a Service: you rent VMs, disks and networks and manage the OS and everything above it (EC2, Azure VMs, Compute Engine). This is where a Linux admin lives', 'Infrastructure as a Service: VMs, disks aur networks kiraye par, OS aur uske upar ka sab tum sambhalte ho (EC2, Azure VMs, Compute Engine). Linux admin yahin rehta hai'],
          ['PaaS', 'Platform as a Service: you give code, the provider runs the servers and the OS (Elastic Beanstalk, App Service, Cloud Run, managed databases like RDS)', 'Platform as a Service: tum code dete ho, provider servers aur OS chalata hai (Elastic Beanstalk, App Service, Cloud Run, RDS jaise managed databases)'],
          ['SaaS', 'Software as a Service: you just use the application (Gmail, Microsoft 365, Salesforce)', 'Software as a Service: tum bas application use karte ho (Gmail, Microsoft 365, Salesforce)'],
          ['public / private / hybrid', 'shared provider cloud / a cloud only for one company (OpenStack, VMware) / a mix of both. Multi-cloud = more than one provider', 'saajha provider cloud / sirf ek company ka cloud (OpenStack, VMware) / dono ka mel. Multi-cloud = ek se zyada provider'],
          ['region / availability zone', 'a region is a geographic area (ap-south-1 = Mumbai); an AZ is one or more data centres inside it (ap-south-1a). Spread across AZs so that one fire does not take you down', 'region ek bhaugolik kshetra hai (ap-south-1 = Mumbai); AZ uske andar ek ya zyada data centres (ap-south-1a). AZs mein faila do taaki ek aag tumhe na gira de'],
          ['shared responsibility', 'the provider secures the building, hardware and hypervisor; YOU secure the OS, patches, firewall rules, users, data and keys', 'provider building, hardware aur hypervisor surakshit karta hai; TUM OS, patches, firewall rules, users, data aur keys surakshit karte ho'],
        ],
        'Term',
        'Term'
      ),
      TABLE(
        [
          ['virtual machine', 'EC2 instance', 'Virtual Machine', 'Compute Engine VM'],
          ['block disk', 'EBS volume', 'Managed Disk', 'Persistent Disk'],
          ['object storage', 'S3 bucket', 'Blob Storage', 'Cloud Storage bucket'],
          ['private network', 'VPC + subnets', 'Virtual Network (VNet)', 'VPC network'],
          ['firewall (instance)', 'Security Group', 'Network Security Group', 'VPC firewall rule'],
          ['load balancer', 'ELB / ALB / NLB', 'Load Balancer / App Gateway', 'Cloud Load Balancing'],
          ['identity', 'IAM users/roles/policies', 'Entra ID + RBAC', 'IAM'],
          ['managed DB', 'RDS', 'Azure SQL / Database for MySQL', 'Cloud SQL'],
          ['DNS', 'Route 53', 'Azure DNS', 'Cloud DNS'],
          ['monitoring', 'CloudWatch', 'Azure Monitor', 'Cloud Monitoring'],
          ['first-boot config', 'user-data + cloud-init', 'custom data + cloud-init', 'startup script / cloud-init'],
          ['IaC (native)', 'CloudFormation', 'ARM / Bicep', 'Deployment Manager'],
        ],
        'Idea',
        'AWS'
      ),
      P('The names differ, the ideas are the same, so learn them **once**: a VM from an image, in a subnet, behind a firewall (security group), with disks, a role instead of passwords, and an SSH key. Whoever knows AWS can find the Azure and GCP equivalents in an afternoon.', 'Naam alag hain, vichar wahi, isliye unhe **ek baar** seekho: image se VM, subnet mein, firewall (security group) ke peeche, disks ke saath, passwords ke bajay role, aur SSH key. Jo AWS jaanta hai wo Azure aur GCP ke barabar ek dopahar mein dhundh leta hai.'),
      H('A Linux server in the cloud: what is different', 'Cloud mein Linux server: kya alag hai'),
      TABLE(
        [
          ['logging in', 'no password: you choose an SSH key pair at launch; the default user depends on the image (ubuntu on Ubuntu, ec2-user on Amazon Linux, azureuser on Azure). Root login is disabled. sudo has no password', 'password nahi: launch par SSH key pair chunte ho; default user image par nirbhar (Ubuntu par ubuntu, Amazon Linux par ec2-user, Azure par azureuser). Root login band. sudo ko password nahi'],
          ['two firewalls', 'the cloud firewall (security group) in front of the VM AND the OS firewall (ufw/firewalld) inside. Both must allow the port: if a service is up but unreachable, check both', 'VM ke aage cloud firewall (security group) AUR andar OS firewall (ufw/firewalld). Dono port allow karein: service chal rahi par pahunch ke bahar ho to dono dekho'],
          ['IP addresses', 'a private IP inside the VPC (stays) and usually a public IP (changes when stopped unless you attach a fixed "Elastic IP"). The VM often does not even know its public IP: ask the metadata service', 'VPC ke andar private IP (rehta hai) aur aam taur par public IP (stop karne par badalta hai jab tak fixed "Elastic IP" na lagao). VM ko aksar apna public IP pata hi nahi hota: metadata service se poochho'],
          ['disks', 'the root disk is a network volume you can resize, snapshot and detach. After growing it in the console you grow the partition and file system inside (growpart, then resize2fs or xfs_growfs: Storage lesson)', 'root disk network volume hai jise resize, snapshot aur detach kar sakte ho. Console mein badhane ke baad andar partition aur file system badhate ho (growpart, phir resize2fs ya xfs_growfs: Storage lesson)'],
          ['disposable', 'instances are cattle: if one is sick, replace it from the image/code rather than nursing it. Keep state (data) on separate volumes or managed services, and keep the setup in cloud-init/Ansible/Terraform', 'instances pashu hain: ek beemar ho to use sambhalne ke bajay image/code se badal do. State (data) alag volumes ya managed services par rakho, aur setup cloud-init/Ansible/Terraform mein'],
          ['identity', 'give the VM an IAM **role** so that programs on it get short-lived credentials from the metadata service. Never copy long-lived access keys onto servers', 'VM ko IAM **role** do taaki us par ke programs metadata service se kam samay ke credentials paayein. Lambe samay ki access keys servers par kabhi copy mat karo'],
        ],
        'Topic',
        'Vishay'
      ),
      H('The instance metadata service', 'Instance metadata service'),
      P('Every cloud VM can ask a special link-local address, **169.254.169.254**, about itself: its ID, type, zone, IP addresses, the user-data it was started with, and even temporary credentials for its IAM role. No login needed, it only works from inside the VM. Scripts use it to learn "who am I and where am I".', 'Har cloud VM ek khaas link-local address, **169.254.169.254**, se apne baare mein pooch sakti hai: uski ID, type, zone, IP addresses, jis user-data se shuru hui, aur apne IAM role ke temporary credentials bhi. Login nahi chahiye, sirf VM ke andar se kaam karta hai. Scripts isse "main kaun hoon aur kahan hoon" jaante hain.'),
      CMD(['curl -s http://169.254.169.254/latest/meta-data/', 'curl -s http://169.254.169.254/latest/meta-data/instance-id; echo', 'curl -s http://169.254.169.254/latest/meta-data/instance-type; echo', 'curl -s http://169.254.169.254/latest/meta-data/placement/availability-zone; echo', 'curl -s http://169.254.169.254/latest/meta-data/local-ipv4; echo', 'curl -s http://169.254.169.254/latest/meta-data/public-ipv4; echo', 'curl -s http://169.254.169.254/latest/dynamic/instance-identity/document', 'curl -s http://169.254.169.254/latest/user-data'], 'The paths ending in / are directories you can walk. The same AWS-style tree exists in the sandbox (Azure and GCP have equivalents with a required header). Use it in scripts: INSTANCE_ID=$(curl -s .../instance-id) to tag logs or name backups.', 'Jo paths / par khatam hote hain wo directories hain jinme ghoom sakte ho. Sandbox mein bhi wahi AWS-style tree hai (Azure aur GCP mein ek zaroori header ke saath barabar ke hain). Scripts mein use karo: INSTANCE_ID=$(curl -s .../instance-id) logs tag karne ya backups ka naam rakhne ke liye.'),
      WARN('The metadata service is a juicy target. If a web application on the VM can be tricked into fetching a URL (an **SSRF** bug), an attacker can make it request `http://169.254.169.254/latest/meta-data/iam/security-credentials/ROLE` and steal the role\'s credentials. Defence: require **IMDSv2** (a session token obtained with a PUT request, which simple SSRF cannot do), lower the hop limit, give the role only the permissions it needs, and block 169.254.169.254 for containers that do not need it.', 'Metadata service ek lalchi nishana hai. Agar VM par web application ko URL fetch karne ke liye bahkaya ja sake (**SSRF** bug), attacker use `http://169.254.169.254/latest/meta-data/iam/security-credentials/ROLE` maangne par majboor karke role ke credentials chura sakta hai. Bachav: **IMDSv2** zaroori karo (PUT request se mila session token, jo saadi SSRF nahi kar sakti), hop limit kam karo, role ko sirf zaroori permissions do, aur jin containers ko zaroorat nahi unke liye 169.254.169.254 block karo.'),
      CMD(['curl -s http://169.254.169.254/latest/meta-data/iam/security-credentials/', 'curl -s http://169.254.169.254/latest/meta-data/iam/security-credentials/web-app-role', 'sudo cloudlab imds v2-required', 'curl -s -o /dev/null -w "plain request: %{http_code}\\n" http://169.254.169.254/latest/meta-data/instance-id', 'TOKEN=$(curl -s -X PUT http://169.254.169.254/latest/api/token -H "X-aws-ec2-metadata-token-ttl-seconds: 300")', 'curl -s -H "X-aws-ec2-metadata-token: $TOKEN" http://169.254.169.254/latest/meta-data/instance-id; echo', 'sudo cloudlab imds optional'], 'The first two lines show how a program gets short-lived role credentials without any stored secret. Then IMDSv2 is switched on (cloudlab is a SANDBOX-only helper; on AWS you set HttpTokens=required on the instance): a plain GET now answers 401, and only a request carrying the token from the PUT works.', 'Pehli do lines dikhati hain ki program bina rakhe secret ke kam samay ke role credentials kaise leta hai. Phir IMDSv2 chalu hota hai (cloudlab SIRF SANDBOX ka helper hai; AWS par instance par HttpTokens=required set karte ho): seedha GET ab 401 deta hai, aur sirf PUT se mile token wali request chalti hai.'),
      H('cloud-init: configure a server at first boot', 'cloud-init: pehli boot par server configure karo'),
      P('When a new VM boots from a generic image, **cloud-init** reads the **user-data** you supplied at launch and configures the machine: hostname, users and SSH keys, packages, files, commands. It runs once per instance (and again if the instance ID changes). The most common format is a YAML file whose first line is exactly `#cloud-config`; a plain shell script starting with `#!` also works.', 'Jab naya VM generic image se boot hota hai, **cloud-init** launch par diya **user-data** padhta hai aur machine configure karta hai: hostname, users aur SSH keys, packages, files, commands. Ye har instance par ek baar chalta hai (aur instance ID badle to dobara). Sabse aam format YAML file hai jiski pehli line bilkul `#cloud-config` ho; `#!` se shuru hone wali saadi shell script bhi chalti hai.'),
      PRE(UD_GOOD.join('\n')),
      TABLE(
        [
          ['hostname / fqdn', 'set the machine name', 'machine ka naam set karo'],
          ['users', 'create accounts with groups, sudo rule, shell and ssh_authorized_keys', 'groups, sudo rule, shell aur ssh_authorized_keys ke saath accounts banao'],
          ['packages / package_update / package_upgrade', 'apt update, upgrade and install', 'apt update, upgrade aur install'],
          ['write_files', 'create files with content, owner and permissions', 'content, owner aur permissions ke saath files banao'],
          ['runcmd', 'commands run once at the end of the first boot (as root)', 'pehli boot ke ant mein ek baar chalne wale commands (root ki tarah)'],
          ['bootcmd', 'commands that run very early on EVERY boot (rarely needed)', 'bahut jaldi HAR boot par chalne wale commands (kam zaroorat)'],
          ['timezone, ntp, ssh_pwauth, disable_root', 'basic OS settings', 'basic OS settings'],
        ],
        'Key',
        'Key'
      ),
      CMD(['cd ~', here('user-data.yml', UD_GOOD), 'cloud-init schema --config-file user-data.yml', 'cloudlab boot user-data.yml', 'ssh demo-server "hostname; id deploy; cat /etc/motd; dpkg -l | grep -c nginx"'], 'cloud-init schema checks the file BEFORE you launch a server with it (a typo in user-data is silently ignored on a real boot: the VM comes up unconfigured and you only find out later). cloudlab boot is a SANDBOX helper that plays the first boot of a fresh server (demo-server) from your file and prints a cloud-init style log; then ssh in and verify.', 'cloud-init schema file ko server launch karne se PEHLE check karta hai (asli boot par user-data ki typo chupchaap ignore hoti hai: VM bina configure hue uthti hai aur baad mein pata chalta hai). cloudlab boot SANDBOX helper hai jo tumhari file se naye server (demo-server) ki pehli boot khelta hai aur cloud-init jaisa log chhapta hai; phir ssh karke verify karo.'),
      CMD(['cat /var/lib/cloud/instance/user-data.txt', 'cloud-init status --long', 'sudo tail -n 5 /var/log/cloud-init.log', 'sudo cat /var/log/cloud-init-output.log', 'cat /etc/cloud/cloud.cfg | head -n 20', 'cloud-init query instance_id'], 'Debugging a server that did not configure itself: the received user-data is stored in /var/lib/cloud/instance/, the status says done/running/error, /var/log/cloud-init.log is the detailed trace and /var/log/cloud-init-output.log holds the output of your runcmd commands (the first place to look when a command failed). cloud-init clean lets it run again on the next boot.', 'Jo server khud configure nahi hua uska debug: mila hua user-data /var/lib/cloud/instance/ mein rakha hota hai, status done/running/error batata hai, /var/log/cloud-init.log vistrit trace hai aur /var/log/cloud-init-output.log mein tumhare runcmd commands ka output hota hai (command fail ho to sabse pehle yahi dekho). cloud-init clean ise agli boot par dobara chalne deta hai.'),
      CMD(UD_BAD_LAB.concat(['cloud-init schema --config-file bad.yml', 'sed -i "1i #cloud-config" bad.yml', 'cloud-init schema --config-file bad.yml', 'sed -i "s/packges:/packages:/" bad.yml', 'cloud-init schema --config-file bad.yml']), 'Two classic mistakes: the missing #cloud-config first line (the whole file is ignored) and a misspelled key (packges). The schema checker names the problem before it costs you a failed deployment.', 'Do classic galtiyan: #cloud-config pehli line ka na hona (poori file ignore hoti hai) aur galat likha key (packges). Schema checker deployment fail hone se pehle samasya ka naam batata hai.'),
      H('Infrastructure as Code with Terraform', 'Terraform ke saath Infrastructure as Code'),
      P('Clicking in a cloud console is fine for learning and terrible for production: nobody remembers what was clicked, you cannot review it, and rebuilding the same setup in another region is guesswork. **Infrastructure as Code (IaC)** writes the infrastructure in text files that live in Git. **Terraform** (and its open-source fork OpenTofu) is the most widely used tool: you describe the **desired end state** in HCL, and Terraform works out what to create, change or destroy by comparing it with the **state** it recorded last time. One tool, thousands of **providers** (AWS, Azure, GCP, Kubernetes, GitHub, DNS...).', 'Cloud console mein click karna seekhne ke liye theek hai aur production ke liye bura: kisi ko yaad nahi kya click kiya, review nahi ho sakta, aur doosre region mein wahi setup dobara banana andaza hai. **Infrastructure as Code (IaC)** infrastructure ko text files mein likhta hai jo Git mein rehti hain. **Terraform** (aur uska open-source fork OpenTofu) sabse zyada use hone wala tool hai: tum HCL mein **chahi hui antim halat** likhte ho, aur Terraform pichhli baar yaad ki **state** se tulna karke tay karta hai kya banana, badalna ya hatana hai. Ek tool, hazaaron **providers** (AWS, Azure, GCP, Kubernetes, GitHub, DNS...).'),
      STEPS([
        ['`terraform init`: download the providers the configuration needs and prepare the folder (creates .terraform/ and .terraform.lock.hcl).', '`terraform init`: configuration ko jo providers chahiye download karo aur folder taiyar karo (.terraform/ aur .terraform.lock.hcl banta hai).'],
        ['`terraform fmt` and `terraform validate`: format the code and check syntax and references without touching anything.', '`terraform fmt` aur `terraform validate`: code format karo aur kuch chhue bina syntax aur references check karo.'],
        ['`terraform plan`: compare code, state and reality and show exactly what WOULD happen: `+` create, `~` change in place, `-/+` replace, `-` destroy. Read it every time.', '`terraform plan`: code, state aur asliyat ki tulna karke theek dikhao kya HOGA: `+` create, `~` jagah par badlav, `-/+` replace, `-` destroy. Har baar padho.'],
        ['`terraform apply`: make it so (asks for "yes"); the state file is updated.', '`terraform apply`: karwa do (“yes” poochta hai); state file update hoti hai.'],
        ['`terraform destroy` (or remove the block and apply): tear down what the code created.', '`terraform destroy` (ya block hatao aur apply): code ne jo banaya use giraao.'],
      ]),
      PRE(`resource "local_file" "motd" {            # resource TYPE and a local NAME
  filename = "\${path.module}/motd.txt"     # arguments
  content  = "owner: \${var.owner}\\n"      # a variable inside a string
}

output "motd_path" {                       # printed after apply
  value = local_file.motd.filename         # TYPE.NAME.ATTRIBUTE: a reference
}`),
      P('Terraform uses the **references** to order things: because the output uses `local_file.motd`, the file is created first. In a real cloud the same mechanism wires a subnet to the VPC it lives in and a server to its security group. In this sandbox the `local` provider creates files, and a pretend `sandbox` provider creates servers and buckets, so that you can practise the whole cycle safely and for free.', 'Terraform **references** se kram tay karta hai: kyunki output `local_file.motd` use karta hai, file pehle banti hai. Asli cloud mein yahi tareeka subnet ko uske VPC se aur server ko uske security group se jodta hai. Is sandbox mein `local` provider files banata hai, aur natak ka `sandbox` provider servers aur buckets banata hai, taaki poora chakra surakshit aur muft practice ho sake.'),
      CMD(TF1_FIX.slice(0, 4).concat(['terraform init', 'terraform fmt', 'terraform validate', 'terraform plan']), 'Run init once per folder. The plan shows one resource to create: every attribute with "+" and the ones only the provider knows after creation as "(known after apply)". Nothing exists yet.', 'init folder ke liye ek baar chalao. Plan ek resource banane ko dikhata hai: har attribute "+" ke saath aur jo sirf provider ko banne ke baad pata hote hain wo "(known after apply)". Abhi kuch bana nahi.'),
      CMD(['terraform apply', 'cat motd.txt', 'terraform state list', 'terraform output', 'terraform plan'], 'apply shows the plan again and waits for you to type yes. Afterwards the second plan says "No changes. Your infrastructure matches the configuration": idempotency, the same idea as Ansible.', 'apply plan dobara dikhata hai aur tumse yes type karne ka intezar karta hai. Baad mein doosra plan kehta hai "No changes. Your infrastructure matches the configuration": idempotency, Ansible jaisa hi vichar.'),
      CMD(['sed -i \'s/default = "asha"/default = "ravi"/\' main.tf', 'terraform plan', 'terraform apply -auto-approve', 'cat motd.txt', 'echo "someone edited this by hand" > motd.txt', 'terraform plan', 'terraform apply -auto-approve', 'cat motd.txt'], 'Change the code and plan shows the change; for a local_file a new content means "must be replaced" (-/+). Then manual drift: somebody edits the real thing, the next plan notices that reality differs from the code and apply puts it back. This is why IaC beats clicking: the code is the single source of truth.', 'Code badlo to plan badlav dikhata hai; local_file ke liye naya content matlab "must be replaced" (-/+). Phir manual drift: kisi ne asli cheez haath se badli, agla plan dekhta hai ki asliyat code se alag hai aur apply use wapas laga deta hai. IaC isliye click karne se behtar hai: code hi sach ka ek srot hai.'),
      H('A pretend cloud: servers, count, and outputs', 'Natak ka cloud: servers, count aur outputs'),
      CMD(TF2_FIX.slice(1, 4).concat(['terraform init', 'terraform plan | tail -n 25', 'terraform apply -auto-approve', 'terraform output server_ips', 'terraform state list', 'terraform state show \'sandbox_server.web[0]\'']), 'count = 2 creates two servers web[0] and web[1]; `sandbox_server.web[*].public_ip` is a "splat" that collects an attribute from all of them. In AWS this would be an aws_instance and an aws_s3_bucket: the workflow and the syntax are identical.', 'count = 2 do servers web[0] aur web[1] banata hai; `sandbox_server.web[*].public_ip` "splat" hai jo sab se ek attribute ikattha karta hai. AWS mein ye aws_instance aur aws_s3_bucket hota: workflow aur syntax bilkul wahi.'),
      CMD(['sed -i \'s/size  = "small"/size  = "medium"/\' main.tf', 'terraform plan | grep -E "will be|size|forces|Plan"', 'terraform apply -auto-approve', 'sed -i \'s/image = "ubuntu-24.04"/image = "ubuntu-22.04"/\' main.tf', 'terraform plan | grep -E "will be|image|forces|Plan"', 'terraform destroy -auto-approve'], 'Changing size is an in-place update (~): the server keeps its ID. Changing the image forces replacement (-/+): the server is destroyed and created again, which is exactly what the "# forces replacement" note warns about. Always read which symbol appears before you apply on production.', 'size badalna jagah par update (~) hai: server ki ID wahi rehti hai. image badalna replacement (-/+) majboor karta hai: server hatakar dobara banta hai, jiske baare mein "# forces replacement" note chetata hai. Production par apply se pehle hamesha dekho kaun sa symbol aaya.'),
      WARN('**State is the crown jewel and a risk.** `terraform.tfstate` maps your code to real resources and often contains secrets (passwords, keys) in plain text. Never commit it to Git. For a team, store it in a **remote backend** (an S3 bucket with versioning + encryption and a lock table, or Terraform Cloud) so that everyone shares one state and two people cannot apply at the same time. Never edit it by hand; use `terraform state ...` commands. Treat `destroy` and any `-/+` in a plan with the respect you give `rm -rf`.', '**State sabse keemti bhi hai aur khatra bhi.** `terraform.tfstate` tumhare code ko asli resources se jodta hai aur aksar secrets (passwords, keys) plain text mein rakhta hai. Use Git mein commit kabhi mat karo. Team ke liye use **remote backend** mein rakho (versioning + encryption aur lock table wala S3 bucket, ya Terraform Cloud) taaki sab ek state share karein aur do log ek saath apply na kar sakein. Haath se edit kabhi nahi; `terraform state ...` commands use karo. `destroy` aur plan mein kisi bhi `-/+` ko utna samman do jitna `rm -rf` ko.'),
      TABLE(
        [
          ['variable "x" {}', 'inputs: type, default, description, validation; set with -var, terraform.tfvars or TF_VAR_x', 'inputs: type, default, description, validation; -var, terraform.tfvars ya TF_VAR_x se set'],
          ['locals {}', 'named expressions to avoid repeating yourself', 'naam wale expressions taaki dohrana na pade'],
          ['output "x" {}', 'values to show after apply and to pass to other tools/modules', 'apply ke baad dikhane aur doosre tools/modules ko dene ki values'],
          ['count / for_each', 'make several copies of a resource from a number / a list or map', 'ek resource ki kai copies, ek number / list ya map se'],
          ['depends_on, lifecycle', 'explicit ordering; prevent_destroy, create_before_destroy, ignore_changes', 'saaf kram; prevent_destroy, create_before_destroy, ignore_changes'],
          ['module', 'a reusable folder of Terraform code (a "vpc" module used for dev, staging and prod)', 'Terraform code ka dobara use hone wala folder (dev, staging aur prod mein "vpc" module)'],
          ['data "type" "name" {}', 'read something that already exists (the latest Ubuntu AMI, an existing VPC)', 'jo pehle se maujood hai use padho (latest Ubuntu AMI, maujooda VPC)'],
          ['terraform import', 'bring an existing hand-made resource under Terraform control', 'haath se bane maujooda resource ko Terraform ke niyantran mein lao'],
        ],
        'Block',
        'Block'
      ),
      TABLE(
        [
          ['Terraform / OpenTofu', 'CREATES the infrastructure (servers, networks, buckets, DNS, IAM)', 'infrastructure BANATA hai (servers, networks, buckets, DNS, IAM)'],
          ['Ansible', 'CONFIGURES what runs on the servers (packages, files, services, users). Often Terraform creates the VMs and then calls Ansible, or the VM configures itself with cloud-init', 'servers par jo chalta hai use CONFIGURE karta hai (packages, files, services, users). Aksar Terraform VMs banata hai aur phir Ansible bulata hai, ya VM cloud-init se khud configure hoti hai'],
          ['CloudFormation, ARM/Bicep, Pulumi', 'other IaC tools: provider-specific (CloudFormation, Bicep) or real programming languages (Pulumi, CDK). Same ideas', 'doosre IaC tools: provider-specific (CloudFormation, Bicep) ya asli programming languages (Pulumi, CDK). Vichar wahi'],
          ['Packer', 'builds the golden images (AMIs) that Terraform then launches', 'golden images (AMIs) banata hai jinhe Terraform phir launch karta hai'],
        ],
        'Tool',
        'Tool'
      ),
      H('Cloud command-line tools (what you will type on the job)', 'Cloud command-line tools (naukri mein kya type karoge)'),
      TABLE(
        [
          ['aws ec2 describe-instances --query "Reservations[].Instances[].[InstanceId,State.Name]"', 'list VMs (AWS CLI; configure with aws configure or, better, an instance role)', 'VMs list karo (AWS CLI; aws configure se ya behtar instance role se)'],
          ['aws s3 ls ; aws s3 cp backup.tgz s3://acme-backups/', 'work with buckets: the off-site copy in your backup plan', 'buckets ke saath kaam: backup plan ki off-site copy'],
          ['az vm list -o table ; gcloud compute instances list', 'the same on Azure and Google Cloud', 'Azure aur Google Cloud par wahi'],
          ['aws sts get-caller-identity', 'who am I? (first command when something is denied)', 'main kaun hoon? (kuch deny ho to pehla command)'],
        ],
        'Command',
        'Command'
      ),
      P('These need real accounts, so they are not in the sandbox. When you get a free-tier account: enable **MFA** on the root user and never use it again, create an admin user/role instead, set a **billing alarm** before anything else, tag every resource (owner, project, env) and **delete what you do not use**. The most common beginner mistake is a forgotten test server (or a leaked access key mining cryptocurrency) and a surprise bill.', 'Inke liye asli accounts chahiye, isliye sandbox mein nahi hain. Free-tier account milne par: root user par **MFA** chalu karo aur use dobara kabhi mat chalao, uski jagah admin user/role banao, kisi bhi cheez se pehle **billing alarm** lagao, har resource tag karo (owner, project, env) aur **jo use nahi karte use hatao**. Beginner ki sabse aam galti bhula hua test server (ya leak hui access key se cryptocurrency mining) aur achanak bill hai.'),
      JOB('Typical questions: "IaaS vs PaaS vs SaaS?", "What is an availability zone and why spread across them?", "What is the shared responsibility model: what is YOU on an EC2 instance?" (OS patches, firewall, users, data), "How do you give an application access to S3 without storing keys on the server?" (an IAM role via the instance profile), "What is cloud-init and where do you look when it did not run?" (user-data, cloud-init status, /var/log/cloud-init-output.log), "Explain terraform plan vs apply, and what is state?", "What happens if two people run terraform apply at once?" (state locking in a remote backend), "A server is reachable by ssh from the VM next door but not from the internet: why?" (security group, route table/IGW, public IP, OS firewall), and "Ansible or Terraform?" (both: Terraform builds, Ansible configures). Even without cloud experience, being able to explain these clearly and show the sandbox exercises makes a junior stand out.', 'Aam sawal: "IaaS vs PaaS vs SaaS?", "Availability zone kya hai aur unmein kyun failate hain?", "Shared responsibility model kya hai: EC2 instance par TUM kya ho?" (OS patches, firewall, users, data), "Server par keys rakhe bina application ko S3 ka access kaise doge?" (instance profile se IAM role), "cloud-init kya hai aur na chale to kahan dekhte ho?" (user-data, cloud-init status, /var/log/cloud-init-output.log), "terraform plan vs apply batao, aur state kya hai?", "do log ek saath terraform apply chalayen to kya hoga?" (remote backend mein state locking), "server paas wali VM se ssh se pahunchta hai par internet se nahi: kyun?" (security group, route table/IGW, public IP, OS firewall), aur "Ansible ya Terraform?" (dono: Terraform banata hai, Ansible configure karta hai). Cloud anubhav ke bina bhi, inhe saaf samjha paana aur sandbox ke abhyaas dikha paana junior ko alag dikhata hai.'),
      THINK('Your Terraform plan says "1 to add, 0 to change, 1 to destroy" for a production database server after a small edit. What do you do before typing yes?', 'Ek chhote edit ke baad tumhare Terraform plan mein production database server ke liye "1 to add, 0 to change, 1 to destroy" aaya. "yes" type karne se pehle kya karoge?', 'Stop and read which attribute shows "# forces replacement": a replacement of a database means data loss. Undo the edit or find a way that updates in place; add lifecycle { prevent_destroy = true } on critical resources; take a snapshot/backup first; run the plan past a colleague; and apply to staging first. Never approve a plan you have not read.', 'Ruko aur dekho kaun sa attribute "# forces replacement" dikha raha hai: database ka replacement matlab data loss. Edit wapas lo ya aisa tareeka dhundho jo jagah par update kare; zaroori resources par lifecycle { prevent_destroy = true } lagao; pehle snapshot/backup lo; plan kisi colleague ko dikhao; aur pehle staging par apply karo. Jo plan padha nahi use kabhi approve mat karo.'),
      H('Cheat sheet', 'Cheat sheet'),
      TABLE([
        ['systemd-detect-virt ; lscpu ; cat /sys/class/dmi/id/*', 'am I in a VM, on what?', 'kya main VM mein hoon, kis par?'],
        ['curl -s http://169.254.169.254/latest/meta-data/ (+ token for IMDSv2)', 'ask the instance about itself', 'instance se uske baare mein poochho'],
        ['cloud-init status --long ; cloud-init schema --config-file F ; /var/log/cloud-init-output.log', 'check and debug first-boot config', 'pehli boot config check aur debug'],
        ['#cloud-config  users: packages: write_files: runcmd:', 'the five keys you use most', 'sabse zyada use hone wale paanch keys'],
        ['qemu-img create|info|resize ; virsh list --all|start|shutdown', 'disk images and KVM guests', 'disk images aur KVM guests'],
        ['terraform init ; fmt ; validate ; plan ; apply ; destroy', 'the Terraform cycle', 'Terraform chakra'],
        ['terraform state list|show ; terraform output', 'look at what Terraform manages', 'dekho Terraform kya sambhal raha hai'],
        ['read the plan: + create, ~ update, -/+ replace, - destroy', 'the most important habit', 'sabse zaroori aadat'],
        ['IaaS/PaaS/SaaS ; region/AZ ; VPC/subnet/security group ; IAM role', 'vocabulary of every cloud', 'har cloud ki shabdavali'],
      ]),
    ],
    missions: [
      M('cloud-m1', 'Ask the instance about itself', 'Instance se uske baare mein poochho', 'Use the instance metadata service to read this server\'s instance ID, availability zone and private IPv4 address, and save them in the file ~/instance.txt in the exact form  id=<id> az=<zone> ip=<ip>  (one line).', 'Instance metadata service se is server ki instance ID, availability zone aur private IPv4 address padho, aur unhe file ~/instance.txt mein bilkul is roop mein ek line mein rakho:  id=<id> az=<zone> ip=<ip>.', 'curl -s http://169.254.169.254/latest/meta-data/instance-id ; .../placement/availability-zone ; .../local-ipv4 ; echo "id=... az=... ip=..." > ~/instance.txt', 'curl -s http://169.254.169.254/latest/meta-data/instance-id ; .../placement/availability-zone ; .../local-ipv4 ; echo "id=... az=... ip=..." > ~/instance.txt', (sh) => /^id=i-[0-9a-f]+ az=ap-south-1a ip=\d+\.\d+\.\d+\.\d+\s*$/m.test(LX.cat(sh, '/home/learner/instance.txt')) && sh.log.some((r) => /169\.254\.169\.254.*instance-id/.test(r.cmd)), META_FIX, { testSolve: META_FIX }),
      M('cloud-m2', 'IMDSv2: use the token', 'IMDSv2: token use karo', 'This instance now requires IMDSv2 (use the lab button): a plain request is refused with 401. Get a session token with a PUT request (TTL 300 seconds), use it in the header X-aws-ec2-metadata-token and save the instance ID in ~/id.txt. (Use the lab button.)', 'Is instance ko ab IMDSv2 chahiye (lab button use karo): seedhi request 401 se mana ho jati hai. PUT request se session token lo (TTL 300 second), use header X-aws-ec2-metadata-token mein lagao aur instance ID ~/id.txt mein rakho. (Lab button use karo.)', 'TOKEN=$(curl -s -X PUT .../latest/api/token -H "X-aws-ec2-metadata-token-ttl-seconds: 300") ; curl -s -H "X-aws-ec2-metadata-token: $TOKEN" .../instance-id > ~/id.txt', 'TOKEN=$(curl -s -X PUT .../latest/api/token -H "X-aws-ec2-metadata-token-ttl-seconds: 300") ; curl -s -H "X-aws-ec2-metadata-token: $TOKEN" .../instance-id > ~/id.txt', (sh) => /^i-[0-9a-f]+$/m.test(LX.cat(sh, '/home/learner/id.txt').trim()) && sh.log.some((r) => /-X\s+PUT.*api\/token/.test(r.cmd)) && sh.log.some((r) => /X-aws-ec2-metadata-token:/.test(r.cmd)), V2_LAB.concat(V2_FIX), { lab: { setup: V2_LAB, en: 'an instance that only answers metadata requests carrying an IMDSv2 token.', hi: 'instance jo sirf IMDSv2 token wali metadata requests ka jawab deta hai.' }, testSolve: V2_LAB.concat(V2_FIX) }),
      M('cloud-m3', 'Boot a server from user-data', 'user-data se server boot karo', 'Write ~/user-data.yml (a valid #cloud-config) that: sets the hostname web-02; installs the packages nginx and htop; creates the user deploy (group sudo, shell /bin/bash, passwordless sudo, any ssh key); writes /etc/motd with the line "Managed by cloud-init"; and enables nginx with runcmd. Check it with cloud-init schema, then boot demo-server from it with cloudlab boot.', '~/user-data.yml likho (valid #cloud-config) jo: hostname web-02 set kare; nginx aur htop packages install kare; user deploy banaye (group sudo, shell /bin/bash, passwordless sudo, koi bhi ssh key); /etc/motd mein "Managed by cloud-init" line likhe; aur runcmd se nginx enable kare. cloud-init schema se check karo, phir cloudlab boot se demo-server ko usse boot karo.', '#cloud-config + hostname + packages + users + write_files + runcmd ; cloud-init schema --config-file user-data.yml ; cloudlab boot user-data.yml', '#cloud-config + hostname + packages + users + write_files + runcmd ; cloud-init schema --config-file user-data.yml ; cloudlab boot user-data.yml', (sh) => { const T2 = host(sh, 'demo-server'); const motd = T2.fs.lookup('/etc/motd'); return T2.hostname === 'web-02' && !!T2.users.deploy && T2.installed.has('nginx') && T2.installed.has('htop') && !!motd && /Managed by cloud-init/.test(motd.content) && sh.log.some((r) => /cloud-init schema/.test(r.cmd) && r.code === 0) && sh.log.some((r) => /cloudlab boot/.test(r.cmd)); }, UD_FIX, { testSolve: UD_FIX }),
      M('cloud-m4', 'Why was the user-data ignored?', 'user-data ignore kyun hui?', 'The file ~/bad.yml is meant to be a cloud-config, but cloud-init rejects it. Run cloud-init schema --config-file bad.yml, find what is wrong (there are two problems) and fix the file until the schema check says "Valid schema". (Use the lab button.)', '~/bad.yml cloud-config hone wali hai par cloud-init use reject karta hai. cloud-init schema --config-file bad.yml chalao, pata karo kya galat hai (do samasyayen hain) aur file tab tak theek karo jab tak schema check "Valid schema" na kahe. (Lab button use karo.)', 'cloud-init schema --config-file bad.yml ; add "#cloud-config" as the first line ; fix packges -> packages', 'cloud-init schema --config-file bad.yml ; pehli line "#cloud-config" jodo ; packges -> packages theek karo', (sh) => { const t = LX.cat(sh, '/home/learner/bad.yml'); const last = sh.log.filter((r) => /cloud-init schema/.test(r.cmd)).pop(); return t.split('\n')[0].trim() === '#cloud-config' && /^packages:/m.test(t) && !!last && last.code === 0 && /Valid schema/.test(last.out); }, UD_BAD_LAB.concat(UD_BAD_FIX), { lab: { setup: UD_BAD_LAB, en: 'a user-data file with a missing header and a misspelled key.', hi: 'user-data file jisme header nahi hai aur ek key galat likha hai.' }, testSolve: UD_BAD_LAB.concat(UD_BAD_FIX) }),
      M('cloud-m5', 'A disk image and a KVM guest', 'Disk image aur KVM guest', 'Install qemu-utils and libvirt-clients. Create a 20 GiB qcow2 disk image ~/vm1.qcow2, grow it by 5 GiB with qemu-img resize, and start the libvirt guest test-vm (it is defined but shut off).', 'qemu-utils aur libvirt-clients install karo. 20 GiB ki qcow2 disk image ~/vm1.qcow2 banao, qemu-img resize se use 5 GiB badhao, aur libvirt guest test-vm shuru karo (defined hai par band hai).', 'qemu-img create -f qcow2 ~/vm1.qcow2 20G ; qemu-img resize ~/vm1.qcow2 +5G ; sudo virsh start test-vm', 'qemu-img create -f qcow2 ~/vm1.qcow2 20G ; qemu-img resize ~/vm1.qcow2 +5G ; sudo virsh start test-vm', (sh) => { const n = sh.fs.lookup('/home/learner/vm1.qcow2'); const v = sh.virsh && sh.virsh.doms.find((d) => d.name === 'test-vm'); return !!n && !!n.disk && n.disk.format === 'qcow2' && n.disk.vsize === 25 * 1073741824 && !!v && v.state === 'running'; }, VM_FIX, { testSolve: VM_FIX }),
      M('cloud-m6', 'Your first Terraform apply', 'Tumhara pehla Terraform apply', 'Install terraform. In a new folder ~/infra write main.tf with a variable owner (default "asha") and a local_file resource motd that creates ~/infra/motd.txt containing "Server managed by Terraform, owner: asha" (use the variable and ${path.module}). Run init, plan and apply.', 'terraform install karo. Naye folder ~/infra mein main.tf likho jisme variable owner (default "asha") aur local_file resource motd ho jo ~/infra/motd.txt banaye jisme "Server managed by Terraform, owner: asha" ho (variable aur ${path.module} use karo). init, plan aur apply chalao.', 'apt install terraform ; main.tf (variable + local_file) ; terraform init ; terraform plan ; terraform apply -auto-approve', 'apt install terraform ; main.tf (variable + local_file) ; terraform init ; terraform plan ; terraform apply -auto-approve', (sh) => { const st = tfState(sh, '/home/learner/infra'); return /Server managed by Terraform, owner: asha/.test(LX.cat(sh, '/home/learner/infra/motd.txt')) && tfRes(st, 'local_file') === 1 && /variable "owner"/.test(LX.cat(sh, '/home/learner/infra/main.tf')) && sh.log.some((r) => /terraform plan/.test(r.cmd)); }, TF1_FIX, { testSolve: TF1_FIX }),
      M('cloud-m7', 'Two servers and a bucket from code', 'Code se do servers aur ek bucket', 'In a new folder ~/cloud write a Terraform configuration with a variable env (default "dev"), a sandbox_bucket named "acme-${var.env}-assets" with versioning, TWO sandbox_server resources (use count; image "ubuntu-24.04", size "small") and an output server_ips listing their public IPs. Apply it and list the state.', 'Naye folder ~/cloud mein Terraform configuration likho: variable env (default "dev"), "acme-${var.env}-assets" naam ka sandbox_bucket (versioning ke saath), DO sandbox_server resources (count use karo; image "ubuntu-24.04", size "small") aur output server_ips jo unke public IPs dikhaye. Apply karo aur state list karo.', 'main.tf with sandbox_bucket + sandbox_server count = 2 + output ; terraform init ; apply -auto-approve ; terraform state list', 'main.tf with sandbox_bucket + sandbox_server count = 2 + output ; terraform init ; apply -auto-approve ; terraform state list', (sh) => { const st = tfState(sh, '/home/learner/cloud'); return tfRes(st, 'sandbox_server') === 2 && tfRes(st, 'sandbox_bucket') === 1 && !!st.outputs.server_ips && st.outputs.server_ips.value.length === 2 && sh.log.some((r) => /terraform state list/.test(r.cmd)); }, TF2_FIX, { testSolve: TF2_FIX }),
      M('cloud-m8', 'Somebody edited production by hand', 'Kisi ne production haath se badal diya', 'The folder ~/drift is managed by Terraform (app.conf must contain "max_clients = 100"), but somebody changed the file by hand. Use terraform plan to see the drift, then apply to restore the configured state, and confirm with a final plan that nothing is left to change. (Use the lab button.)', 'Folder ~/drift Terraform se manage hota hai (app.conf mein "max_clients = 100" hona chahiye), par kisi ne file haath se badal di. terraform plan se drift dekho, phir apply se configured halat wapas lao, aur aakhri plan se confirm karo ki badalne ko kuch bacha nahi. (Lab button use karo.)', 'cd ~/drift ; terraform plan ; terraform apply -auto-approve ; terraform plan', 'cd ~/drift ; terraform plan ; terraform apply -auto-approve ; terraform plan', (sh) => { const lastPlan = sh.log.filter((r) => /terraform plan/.test(r.cmd)).pop(); return LX.cat(sh, '/home/learner/drift/app.conf').trim() === 'max_clients = 100' && !!lastPlan && /No changes/.test(lastPlan.out) && sh.log.some((r) => /terraform apply/.test(r.cmd) && /drift/.test(r.cwd || '') || /terraform apply/.test(r.cmd)); }, DRIFT_LAB.concat(DRIFT_FIX), { lab: { setup: DRIFT_LAB, en: 'a Terraform project whose config file was edited by hand after the apply.', hi: 'Terraform project jiski config file apply ke baad haath se badli gayi.' }, testSolve: DRIFT_LAB.concat(DRIFT_FIX) }),
    ],
    quiz: [
      mcq(1, 'You rent virtual machines and are responsible for the operating system, patches and firewall inside them. Which cloud service model is that?', 'Tum virtual machines kiraye par lete ho aur unke andar OS, patches aur firewall tumhari zimmedari hai. Ye kaun sa cloud service model hai?', ['SaaS', 'PaaS', 'IaaS', 'FaaS only'], 2, 'IaaS gives you the infrastructure; everything from the OS up is yours.', 'IaaS infrastructure deta hai; OS se upar ka sab tumhara hai.'),
      mcq(2, 'What is cloud-init used for?', 'cloud-init kis kaam aata hai?', ['Monitoring CPU usage', 'Configuring a new instance at first boot from the user-data you provide', 'Creating the VPC network', 'Encrypting the disk'], 1, 'It reads user-data (hostname, users, packages, files, commands) on the first boot.', 'Ye pehli boot par user-data (hostname, users, packages, files, commands) padhta hai.'),
      cmd(3, 'Print the instance ID of this server from the metadata service (169.254.169.254).', 'Metadata service (169.254.169.254) se is server ki instance ID chhapo.', { setup: [], verify: (sh, r) => /^i-[0-9a-f]{17}$/m.test(r.out.trim()), sample: 'curl -s http://169.254.169.254/latest/meta-data/instance-id', alt: ['curl http://169.254.169.254/latest/meta-data/instance-id', 'curl -s 169.254.169.254/latest/meta-data/instance-id', 'wget -qO- http://169.254.169.254/latest/meta-data/instance-id'], wrong: ['curl -s http://169.254.169.254/latest/meta-data/', 'hostname'], hintEn: 'curl the link-local address, path /latest/meta-data/instance-id.', hintHi: 'link-local address par curl, path /latest/meta-data/instance-id.' }, 'The metadata tree is walked with plain HTTP requests.', 'Metadata tree saadi HTTP requests se dekha jata hai.'),
      cmd(4, 'Which virtualization technology is this server running on? Use the systemd tool made for this.', 'Ye server kaun si virtualization technology par chal raha hai? Isi kaam ka bana systemd tool use karo.', { setup: [], verify: (sh, r) => r.out.trim() === 'kvm', sample: 'systemd-detect-virt', alt: ['systemd-detect-virt --vm', 'systemd-detect-virt -v'], wrong: ['systemd-detect-virt --container', 'lscpu'], hintEn: 'systemd-detect-virt.', hintHi: 'systemd-detect-virt.' }, 'It prints kvm, vmware, docker, none...', 'Ye kvm, vmware, docker, none... chhapta hai.'),
      cmd(5, 'Validate the cloud-config file ~/ud.yml with cloud-init before using it.', 'Use karne se pehle cloud-init se cloud-config file ~/ud.yml validate karo.', { setup: [here('ud.yml', UD_GOOD)], cwd: '~', verify: (sh, r) => /Valid schema/.test(r.out), sample: 'cloud-init schema --config-file ud.yml', alt: ['cloud-init schema -c ud.yml', 'cloud-init schema --config-file ~/ud.yml'], wrong: ['cloud-init status', 'cat ud.yml'], hintEn: 'cloud-init schema with --config-file.', hintHi: 'cloud-init schema, --config-file ke saath.' }, 'The schema check catches a missing header or a misspelled key before you launch.', 'Schema check launch se pehle missing header ya galat key pakad leta hai.'),
      cmd(6, 'Create a 10 GiB disk image in qcow2 format named disk.qcow2 in the current folder.', 'Current folder mein disk.qcow2 naam ki qcow2 format ki 10 GiB disk image banao.', { setup: ['sudo apt install -y qemu-utils'], cwd: '~', verify: (sh) => { const n = sh.fs.lookup('/home/learner/disk.qcow2'); return !!n && !!n.disk && n.disk.format === 'qcow2' && n.disk.vsize === 10 * 1073741824; }, sample: 'qemu-img create -f qcow2 disk.qcow2 10G', alt: ['qemu-img create -f qcow2 ~/disk.qcow2 10G', 'qemu-img create -f qcow2 disk.qcow2 10240M'], wrong: ['qemu-img create disk.qcow2 10G', 'qemu-img create -f raw disk.qcow2 10G'], hintEn: 'qemu-img create -f FORMAT NAME SIZE.', hintHi: 'qemu-img create -f FORMAT NAAM SIZE.' }, 'The -f flag selects the format; qcow2 grows on demand.', '-f flag format chunta hai; qcow2 zaroorat par badhta hai.'),
      cmd(7, 'In the Terraform project ~/q (main.tf is there), initialize the working directory.', 'Terraform project ~/q mein (main.tf wahin hai) working directory initialize karo.', { setup: Q_TF, cwd: '~/q', verify: (sh) => !!sh.fs.lookup('/home/learner/q/.terraform.lock.hcl'), sample: 'terraform init', alt: ['terraform init -input=false'], wrong: ['terraform plan', 'terraform validate'], hintEn: 'The first Terraform command in any folder.', hintHi: 'Kisi bhi folder mein pehla Terraform command.' }, 'init downloads providers and writes the lock file.', 'init providers download karta hai aur lock file likhta hai.'),
      cmd(8, 'In ~/q (already initialized) show what Terraform WOULD do, without changing anything.', '~/q mein (pehle se initialized) dikhao Terraform KYA karega, kuch badle bina.', { setup: Q_TF.concat(['terraform init']), cwd: '~/q', verify: (sh, r) => /Plan: 1 to add, 0 to change, 0 to destroy/.test(r.out) && !sh.fs.lookup('/home/learner/q/terraform.tfstate'), sample: 'terraform plan', alt: ['terraform plan -input=false', 'terraform plan -no-color'], wrong: ['terraform apply -auto-approve', 'terraform init'], hintEn: 'The dry-run command of Terraform.', hintHi: 'Terraform ka dry-run command.' }, 'plan compares code, state and reality and only reports.', 'plan code, state aur asliyat ki tulna karta hai aur sirf report karta hai.'),
      mcq(9, 'Why must terraform.tfstate not be committed to a public Git repository?', 'terraform.tfstate ko public Git repository mein commit kyun nahi karna chahiye?', ['It is too large for Git', 'It often contains secrets in plain text and is the live record of your infrastructure; use a remote backend instead', 'Git cannot store JSON files', 'Terraform deletes it after every apply'], 1, 'State can hold passwords and keys and must be shared with locking: a remote backend.', 'State mein passwords aur keys ho sakti hain aur use locking ke saath share karna chahiye: remote backend.'),
      cmd(10, 'Boss level: in ~/q (initialized) create the infrastructure without the confirmation prompt and then print the output named bucket, in one command line.', 'Boss level: ~/q mein (initialized) confirmation prompt ke bina infrastructure banao aur phir bucket naam ka output chhapo, ek hi command line mein.', { setup: Q_TF.concat(['terraform init']), cwd: '~/q', verify: (sh, r) => (r.out.match(/arn:sandbox:s3:::acme-quiz/g) || []).length >= 2 && tfRes(tfState(sh, '/home/learner/q'), 'sandbox_bucket') === 1, sample: 'terraform apply -auto-approve && terraform output bucket', alt: ['terraform apply -auto-approve; terraform output -raw bucket', 'terraform apply -auto-approve && terraform output -raw bucket'], wrong: ['terraform apply -auto-approve', 'terraform output bucket'], hintEn: 'apply -auto-approve, then output NAME, joined with &&.', hintHi: 'apply -auto-approve, phir output NAAM, && se joda hua.' }, '-auto-approve skips the yes prompt (never in production pipelines without a reviewed plan); output prints a named value from the state.', '-auto-approve yes prompt chhod deta hai (production pipelines mein review kiye plan ke bina kabhi nahi); output state se naam wali value chhapta hai.'),
    ],
  });
})();
